"use client";import {useEffect,useState} from "react";import {useParams} from "next/navigation";import AdminShell,{PageHeader} from "../../../../../components/admin/admin-shell";import VendorForm from "../../../../../components/admin/vendor-form";export default function EditVendor(){const {id}=useParams<{id:string}>();const [item,setItem]=useState<any>(null);useEffect(()=>{fetch(`/api/admin/vendors/${id}`).then(r=>r.json()).then(d=>setItem(d.item))},[id]);return <AdminShell><PageHeader title="Edit vendor" description="Update marketplace information; changes are reflected publicly."/>{item?<VendorForm initial={item} id={id}/>:<p className="text-black/50">Loading vendor…</p>}</AdminShell>}
